export const SIGNAL_DELAYS={moon:{seconds:384400/299792.458,label:'~1.3 seconds',route:'Direct Line-of-Sight to Deep Space Network'},mars:{seconds:14*60,label:'~14 minutes',route:'DSN Goldstone / Madrid Relay · Speed compressed for play'},titan:{seconds:82*60,label:'~82 minutes',route:'DSN Canberra Relay · Speed compressed for play'}};
export function signalMarkup(destination){const d=SIGNAL_DELAYS[destination]||SIGNAL_DELAYS.titan;return `<b>Signal to Earth · ${d.label} one way</b><span>${d.route}</span><svg viewBox="0 0 320 50" role="img" aria-label="Radio signal travelling from spacecraft to Earth"><path d="M25 25H295" stroke="#b7d6c466" stroke-dasharray="4 5"/><circle cx="25" cy="25" r="8" fill="#f1d08c"/><circle cx="295" cy="25" r="12" fill="#84c9d6"/><g class="signal-ping"><circle cx="25" cy="25" r="5" fill="#f8e9b3"/><circle class="signal-ring" cx="25" cy="25" r="9" fill="none" stroke="#aee9c9"/></g><text x="25" y="49">PIP</text><text x="275" y="49">EARTH</text></svg><small>${destination==='moon'?'Mean Earth–Moon distance; actual timing varies.':'Representative delay; varies with orbital geometry. Relay assignment is illustrative.'} Confirmation compressed for play.</small>`;}
